/// <summary>
/// Logic Block component that handles data collection for license plates on inventory journals
/// </summary>
class MwmsLogicComponentInventoryJournalLicensePlates extends MwmsLogicComponentInventoryJournalId
{

}

Method.Source:
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    TFMReferenceDataConfiguration   ret = super();
    TFMRegistrationCollectorText    lpCollector = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WHSLicensePlateId));
    lpCollector.parmOptional(false);
    ret.addCollector(lpCollector);        
    return ret;
}

public Common provideDataIfPossible(Common _table)
{
    Common ret;

    ret = super(_table);

    if (_table.TableId == tableNum(WHSLicensePlate))
    {
        ret = this.initLicensePlate(_table);
    }

    return ret;
}

/// <summary>
/// Initiates a License Plate buffer from the request object if none is passed, otherwise returns it
/// </summary>
/// <param name = "_lp">A License Plate Buffer</param>
/// <returns>A license plate buffer</returns>
protected WHSLicensePlate initLicensePlate(WHSLicensePlate _lp)
{
    TFMRequestItemAndDimensionElement   docRequest = subComponents.getComponent(classStr(TFMLogicComponentDimensions)).componentRequest(request);

    if (!_lp.RecId)
    {
        //New record
        return WhsLicensePlate::find(docRequest.parmWHSLicensePlateId(), true);
    }
    _lp.selectForUpdate(true);

    return _lp;
}
